# Merge all extended weeks into WEEKLY_NUTRITION
for wk, (theme, foods_list) in EXTENDED_WEEKS_THEMES.items():
    trimester_str = "Second Trimester (Weeks 13-27)" if wk <= 27 else "Third Trimester (Weeks 28-40)"
    formatted_foods = []
    for item in foods_list:
        name, cat, cal, pro, fib, carb, fat, rec = item
        formatted_foods.append({
            "food": name,
            "name": name,
            "category": cat,
            "calories": cal,
            "protein": pro,
            "fiber": fib,
            "carbs": carb,
            "fat": fat,
            "recommendation": rec
        })
    WEEKLY_NUTRITION[wk] = {
        "focus": theme,
        "trimester": trimester_str,
        "foods": formatted_foods
    }

def get_weekly_nutrition(week):
    """
    Returns the distinct curated foods for a given pregnancy week (1 to 40).
    """
    try:
        w = int(week)
    except (ValueError, TypeError):
        w = 1
    w = max(1, min(40, w))
    return WEEKLY_NUTRITION.get(w, WEEKLY_NUTRITION[1])
